content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-color: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --error-color: #ef4444;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 600px;
  margin: 40px auto;
  padding: 20px;
  box-sizing: border-box;
}

.quiz-card {
  background-color: var(--card-bg);
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 24px;
  margin-bottom: 20px;
}

.progress-bar {
  width: 100%;
  height: 8px;
  background-color: var(--border-color);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 24px;
}

.progress-bar-fill {
  height: 100%;
  background-color: var(--primary-color);
  transition: width 0.3s ease;
}

.question-text {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 20px;
  line-height: 1.5;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 500;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
  width: 100%;
  padding: 12px;
  font-size: 1.1rem;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-option {
  display: block;
  width: 100%;
  text-align: left;
  background-color: #ffffff;
  border: 2px solid var(--border-color);
  color: var(--text-color);
  padding: 14px 16px;
  margin-bottom: 12px;
  border-radius: 8px;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-option:hover:not(:disabled) {
  border-color: var(--primary-color);
  background-color: #eff6ff;
}

.btn-option.correct {
  background-color: #d1fae5;
  border-color: var(--success-color);
  color: #065f46;
}

.btn-option.incorrect {
  background-color: #fee2e2;
  border-color: var(--error-color);
  color: #991b1b;
}

.score-container {
  text-align: center;
  padding: 20px 0;
}

.result-title {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 16px;
}

.result-score {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary-color);
  margin-bottom: 24px;
}

.explanation {
  background-color: #f9fafb;
  border-left: 4px solid var(--primary-color);
  padding: 16px;
  margin-top: 20px;
  border-radius: 0 8px 8px 0;
  font-size: 0.95rem;
  line-height: 1.6;
}

@media (max-width: 640px) {
  .app-container {
    margin: 10px;
    padding: 10px;
  }

  .quiz-card {
    padding: 16px;
  }

  .question-text {
    font-size: 1.1rem;
  }
}

export interface Question {
  id: number;
  question: string;
  options: string[];
  answer: number;
  explanation: string;
}

export interface QuizProps {
  question: Question;
  questionNumber: number;
  totalQuestions: number;
  onAnswer: (selectedIndex: number) => void;
}

export interface ResultProps {
  score: number;
  totalQuestions: number;
  questions: Question[];
  userAnswers: number[];
  onRestart: () => void;
}

import { useState } from 'react';
import { QuizProps } from '../types';

export default function Quiz({ question, questionNumber, totalQuestions, onAnswer }: QuizProps) {
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState<boolean>(false);

  const progressPercent = ((questionNumber - 1) / totalQuestions) * 100;

  const handleSelect = (index: number) => {
    if (isAnswered) return;
    setSelectedAnswer(index);
    setIsAnswered(true);
  };

  const handleNext = () => {
    if (selectedAnswer !== null) {
      onAnswer(selectedAnswer);
      setSelectedAnswer(null);
      setIsAnswered(false);
    }
  };

  return (
    <div className="app-container">
      <div className="progress-bar">
        <div className="progress-bar-fill" style={{ width: `${progressPercent}%` }}></div>
      </div>
      <div className="quiz-card">
        <div style={{ fontSize: '0.9rem', color: 'var(--text-muted)', marginBottom: '8px' }}>
          第 {questionNumber} 問 / 全 {totalQuestions} 問
        </div>
        <div className="question-text">{question.question}</div>
        <div>
          {question.options.map((option, index) => {
            let btnClass = "btn-option";
            if (isAnswered) {
              if (index === question.answer) {
                btnClass += " correct";
              } else if (index === selectedAnswer) {
                btnClass += " incorrect";
              }
            }
            return (
              <button
                key={index}
                className={btnClass}
                onClick={() => handleSelect(index)}
                disabled={isAnswered}
              >
                {option}
              </button>
            );
          })}
        </div>

        {isAnswered && (
          <div>
            <div className="explanation">
              <strong>【解説】</strong>
              <p style={{ margin: '8px 0 0 0' }}>{question.explanation}</p>
            </div>
            <div style={{ marginTop: '20px' }}>
              <button className="btn btn-primary" onClick={handleNext}>
                {questionNumber === totalQuestions ? '結果を見る' : '次の問題へ'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { ResultProps } from '../types';

export default function Result({ score, totalQuestions, questions, userAnswers, onRestart }: ResultProps) {
  const percentage = Math.round((score / totalQuestions) * 100);

  return (
    <div className="app-container">
      <div className="quiz-card score-container">
        <div className="result-title">クイズ終了！</div>
        <p style={{ color: 'var(--text-muted)', marginBottom: '10px' }}>あなたの正解数は</p>
        <div className="result-score">{score} / {totalQuestions} 問 ({percentage}%)</div>

        <div style={{ marginBottom: '24px', fontSize: '1.1rem', fontWeight: 500 }}>
          {score === totalQuestions ? 'お見事！全問正解です！素晴らしい地理知識ですね！' :
           score >= totalQuestions / 2 ? 'よくできました！日本の地理に詳しいですね。' :
           'もう少しで全問正解！日本の地理を再確認してみましょう。'}
        </div>

        <button className="btn btn-primary" onClick={onRestart}>
          もう一度挑戦する
        </button>
      </div>

      <div style={{ marginTop: '24px' }}>
        <h3 style={{ fontSize: '1.25rem', marginBottom: '16px' }}>回答の振り返り</h3>
        {questions.map((q, index) => {
          const userAns = userAnswers[index];
          const isCorrect = userAns === q.answer;
          return (
            <div key={q.id} className="quiz-card" style={{ marginBottom: '16px' }}>
              <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '4px' }}>
                第 {index + 1} 問 {isCorrect ? <span style={{ color: 'var(--success-color)', fontWeight: 'bold' }}>【正解】</span> : <span style={{ color: 'var(--error-color)', fontWeight: 'bold' }}>【不正解】</span>}
              </div>
              <div style={{ fontWeight: 600, marginBottom: '12px' }}>{q.question}</div>
              <div style={{ fontSize: '0.95rem', marginBottom: '8px' }}>
                あなたの回答: <span style={{ fontWeight: 500, color: isCorrect ? 'var(--success-color)' : 'var(--error-color)' }}>{q.options[userAns]}</span>
              </div>
              {!isCorrect && (
                <div style={{ fontSize: '0.95rem', marginBottom: '8px' }}>
                  正解: <span style={{ fontWeight: 500, color: 'var(--success-color)' }}>{q.options[q.answer]}</span>
                </div>
              )}
              <div className="explanation" style={{ marginTop: '12px' }}>
                <strong>【解説】</strong>
                <p style={{ margin: '4px 0 0 0' }}>{q.explanation}</p>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Question } from './types';
import Quiz from './components/Quiz';
import Result from './components/Result';
import './index.css';

const questions: Question[] = [
  {
    id: 1,
    question: '日本で一番面積が大きい都道府県はどこでしょう？',
    options: ['岩手県', '北海道', '新潟県', '長野県'],
    answer: 1,
    explanation: '北海道は日本全体の約22%を占める最大の都道府県です。2位は岩手県、3位は福島県となっています。'
  },
  {
    id: 2,
    question: '日本最西端にある日本領の有人島はどこでしょう？',
    options: ['石垣島', '西表島', '与那国島', '宮古島'],
    answer: 2,
    explanation: '沖縄県にある与那国島が日本の最西端の有人島です。天気が良い日には台湾が見えることもあります。'
  },
  {
    id: 3,
    question: 'いわゆる「日本アルプス」に含まれない山脈はどれでしょう？',
    options: ['東アルプス山脈', '飛騨山脈（北アルプス）', '木曽山脈（中央アルプス）', '赤石山脈（南アルプス）'],
    answer: 0,
    explanation: '日本アルプスは飛騨山脈・木曽山脈・赤石山脈の総称です。「東アルプス」という山脈は存在しません。'
  },
  {
    id: 4,
    question: '日本最大の湖である「琵琶湖」がある都道府県はどこでしょう？',
    options: ['京都府', '滋賀県', '岐阜県', '福井県'],
    answer: 1,
    explanation: '琵琶湖は滋賀県に位置し、県土の約6分の1を占めています。日本で最も古い歴史を持つ古代湖の一つでもあります。'
  },
  {
    id: 5,
    question: '日本で一番長い川「信濃川」の流域に含まれない県はどこでしょう？',
    options: ['長野県', '新潟県', '群馬県', '富山県'],
    answer: 3,
    explanation: '信濃川は長野県で「千曲川」と呼ばれて流れ始め、新潟県を経て日本海に注ぎます。群馬県の一部も流域に含まれますが、富山県は含まれません。'
  }
];

export default function App() {
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [userAnswers, setUserAnswers] = useState<number[]>([]);
  const [isFinished, setIsFinished] = useState<boolean>(false);

  const handleAnswer = (selectedIndex: number) => {
    const updatedAnswers = [...userAnswers, selectedIndex];
    setUserAnswers(updatedAnswers);

    if (currentIndex + 1 < questions.length) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setIsFinished(true);
    }
  };

  const handleRestart = () => {
    setCurrentIndex(0);
    setUserAnswers([]);
    setIsFinished(false);
  };

  const score = userAnswers.reduce((acc, ans, idx) => {
    return ans === questions[idx].answer ? acc + 1 : acc;
  }, 0);

  return (
    <div>
      {!isFinished ? (
        <Quiz
          question={questions[currentIndex]}
          questionNumber={currentIndex + 1}
          totalQuestions={questions.length}
          onAnswer={handleAnswer}
        />
      ) : (
        <Result
          score={score}
          totalQuestions={questions.length}
          questions={questions}
          userAnswers={userAnswers}
          onRestart={handleRestart}
        />
      )}
    </div>
  );
}
